// The books of each corpus, with the number of segments (verses, mishnayot or Talmud lines) in each
// section. catalog.json is generated by scripts/build-learning-catalog.mjs from Sefaria.
import type { Corpus } from '../../lib/types'
import data from './catalog.json'
import { hebrewNumeral } from './hebrew'

export type Book = {
  id: string // Sefaria title, used in refs
  en: string
  he: string
  // First section: a chapter number, or for the Talmud an amud index where 2 = 2a, 3 = 2b
  start: number
  lengths: number[] // segment count of each section, starting at `start`
  corpus: Corpus
}

export type BookGroup = { en: string; he: string; books: Book[] }

export type CorpusInfo = {
  id: Corpus
  en: string
  he: string
  section: string // what one section is called
  sections: string
  groups: BookGroup[]
  books: Book[]
}

const raw = data as Record<Corpus, { en: string; he: string; books: Omit<Book, 'corpus'>[] }[]>

function corpus(id: Corpus, en: string, he: string, section: string, sections: string): CorpusInfo {
  const groups = raw[id].map((g) => ({ ...g, books: g.books.map((b) => ({ ...b, corpus: id })) }))
  return { id, en, he, section, sections, groups, books: groups.flatMap((g) => g.books) }
}

export const corpora: Record<Corpus, CorpusInfo> = {
  tanakh: corpus('tanakh', 'Tanach', 'תנ״ך', 'chapter', 'chapters'),
  mishnah: corpus('mishnah', 'Mishna', 'משנה', 'chapter', 'chapters'),
  bavli: corpus('bavli', 'Talmud Bavli', 'תלמוד בבלי', 'amud', 'amudim'),
}

export const corpusList = Object.values(corpora)

// The Hebrew edition the backend loads from Sefaria for each corpus, credited under each text
export const textSources: Record<Corpus, string> = {
  tanakh: 'Miqra according to the Masorah (CC BY-SA), via Sefaria',
  mishnah: 'Torat Emet 357 (public domain), via Sefaria',
  bavli: 'William Davidson Edition, vocalized (CC BY-NC), via Sefaria',
}

const byId = new Map(corpusList.flatMap((c) => c.books.map((b) => [b.id, b] as const)))

export const findBook = (id: string) => byId.get(id)

export const isTalmud = (book: Book) => book.corpus === 'bavli'

/** A section's number in English: "5" for a chapter, "2a" for an amud. `i` is its offset in book.lengths. */
export function sectionName(book: Book, i: number): string {
  const n = book.start + i
  return isTalmud(book) ? `${Math.floor(n / 2) + 1}${n % 2 ? 'b' : 'a'}` : String(n)
}

/** A section's number in Hebrew: "ה׳" for a chapter, "ב׳ ע״א" for an amud. */
export function sectionNameHe(book: Book, i: number): string {
  const n = book.start + i
  return isTalmud(book) ? `${hebrewNumeral(Math.floor(n / 2) + 1)} ע״${n % 2 ? 'ב' : 'א'}` : hebrewNumeral(n)
}

/** The Sefaria ref for a section, such as "Genesis 5" or "Berakhot 2a". */
export const sectionRef = (book: Book, i: number) => `${book.id} ${sectionName(book, i)}`

/** The reader page for a section, optionally scrolled to a 1-based segment. */
export const sectionPath = (book: Book, i: number, segment?: number | null) =>
  `/apps/learning/read/${encodeURIComponent(book.id)}/${sectionName(book, i)}${segment ? `?seg=${segment}` : ''}`

/** Parses "5" or "2a" back to an offset in book.lengths, or -1 if the book has no such section. */
export function sectionIndex(book: Book, name: string): number {
  const m = /^(\d+)([ab])?$/.exec(name)
  if (!m || isTalmud(book) !== !!m[2]) return -1
  const n = isTalmud(book) ? (Number(m[1]) - 1) * 2 + (m[2] === 'b' ? 1 : 0) : Number(m[1])
  const i = n - book.start
  return i >= 0 && i < book.lengths.length ? i : -1
}

export function parseRef(ref: string): { book: Book; index: number } | undefined {
  const m = /^(.+) (\d+[ab]?)$/.exec(ref)
  const book = m && findBook(m[1])
  if (!book) return undefined
  const index = sectionIndex(book, m[2])
  return index < 0 ? undefined : { book, index }
}

/** Hebrew heading for a section: "בראשית פרק ה׳", "משנה ברכות פרק ב׳" or "ברכות דף ב׳ ע״א". */
export function sectionHeading(book: Book, i: number): string {
  return `${book.he} ${isTalmud(book) ? 'דף' : 'פרק'} ${sectionNameHe(book, i)}`
}

/** Hebrew label for a place, with an optional 1-based segment: "בראשית ה׳:ג׳". */
export function placeLabelHe(book: Book, i: number, segment?: number | null): string {
  const base = `${book.he} ${sectionNameHe(book, i)}`
  return segment ? `${base}${isTalmud(book) ? ' ' : ':'}${hebrewNumeral(segment)}` : base
}

/** English label for a place: "Genesis 5:3", "Berakhot 2a:4". */
export function placeLabelEn(book: Book, i: number, segment?: number | null): string {
  return `${book.en} ${sectionName(book, i)}${segment ? `:${segment}` : ''}`
}

/** The section after or before one in the same corpus, crossing into the next or previous book. */
export function adjacentSection(book: Book, i: number, step: 1 | -1): { book: Book; index: number } | undefined {
  const books = corpora[book.corpus].books
  const j = i + step
  if (j >= 0 && j < book.lengths.length) return { book, index: j }
  const next = books[books.indexOf(book) + step]
  if (!next) return undefined
  return { book: next, index: step === 1 ? 0 : next.lengths.length - 1 }
}
